create function public.save_taskboard_workspace_for_user(workspace_user uuid, expected_revision bigint, workspace_data jsonb) returns bigint language plpgsql security invoker set search_path='' as $$ declare result bigint; begin if auth.uid() is null or auth.uid() <> workspace_user then raise exception 'Account changed' using errcode='42501'; end if; if jsonb_typeof(workspace_data)<>'object' or octet_length(workspace_data::text)>5242880 then raise exception 'Invalid workspace' using errcode='22023'; end if; if expected_revision=0 then insert into public.taskboard_workspaces(user_id,data) values(workspace_user,workspace_data) on conflict(user_id) do nothing returning revision into result; else update public.taskboard_workspaces set data=workspace_data,revision=revision+1,updated_at=now() where user_id=workspace_user and revision=expected_revision returning revision into result; end if; if result is null then raise exception 'Workspace changed on another device' using errcode='40001'; end if; return result; end; $$; revoke all on function public.save_taskboard_workspace_for_user(uuid,bigint,jsonb) from public,anon; grant execute on function public.save_taskboard_workspace_for_user(uuid,bigint,jsonb) to authenticated; revoke execute on function public.save_taskboard_workspace(bigint,jsonb) from authenticated;
